  1383          switch (rec_type) {
  1384              case SAV_RECORD_TYPE_VARIABLE:
  1385                  if ((retval = sav_read_variable_record(ctx)) != READSTAT_OK)
  1386                      goto cleanup;
  1387                  break;
  1388              case SAV_RECORD_TYPE_VALUE_LABEL:
  1389                  if ((retval = sav_read_value_label_record(ctx)) != READSTAT_OK)
  1390                      goto cleanup;
