  1427                          /* parsed in pass 1 */
  1428                          break;
  1429                      case SAV_RECORD_SUBTYPE_FP_INFO:
  1430                          retval = sav_parse_machine_floating_point_record(data_buf, size, count, ctx);
  1431                          if (retval != READSTAT_OK)
  1432                              goto cleanup;
  1433                          break;
  1434                      case SAV_RECORD_SUBTYPE_VAR_DISPLAY:
  1435                          retval = sav_store_variable_display_parameter_record(data_buf, size, count, ctx);
  1436                          if (retval != READSTAT_OK)
  1437                              goto cleanup;
  1438                          break;
  1439                      case SAV_RECORD_SUBTYPE_LONG_VAR_NAME:
  1440                          retval = sav_parse_long_variable_names_record(data_buf, count, ctx);
  1441                          if (retval != READSTAT_OK)
  1442                              goto cleanup;
  1443                          break;
  1444                      case SAV_RECORD_SUBTYPE_VERY_LONG_STR:
  1445                          retval = sav_parse_very_long_string_record(data_buf, count, ctx);
  1446                          if (retval != READSTAT_OK)
  1447                              goto cleanup;
  1448                          break;
  1449                      case SAV_RECORD_SUBTYPE_LONG_STRING_VALUE_LABELS:
  1450                          retval = sav_parse_long_string_value_labels_record(data_buf, size, count, ctx);
  1451                          if (retval != READSTAT_OK)
  1452                              goto cleanup;
  1453                          break;
